insert into public.settings (key, value) values ('timers', '{"m1_dashboard_sec": 900, "m1_readout_sec": 300, "m2_debrief_sec": 1500, "grace_sec": 10, "m2_max_plays": 2}'::jsonb);
insert into public.settings (key, value) values ('calibration', '{"double_grade_first_n": 2}'::jsonb);
insert into public.settings (key, value) values ('readout', '{"development_area_below": 3}'::jsonb);
insert into public.settings (key, value) values ('module3', '{"min_practice_minutes": 5, "cards_per_teach_back": 2}'::jsonb);
insert into public.dimensions values (1, 'Content Mastery', 'Recites content; errors in the model', 'Accurate but tied to the script', 'Explains the why and applies the model to the case', 'Adapts the model to new situations and spots its limits');
insert into public.dimensions values (2, 'Facilitation', 'Lectures; learners passive', 'Asks questions but answers them; uneven participation', 'Learners talk more than the facilitator; all included', 'Manages disruption smoothly; energy and pace fit the group');
insert into public.dimensions values (3, 'Coaching Capability', 'Tells the answer', 'Mixes coaching with telling; leading questions', 'Open questions; learner reaches own conclusion and action', 'Questions sharpen as the learner reveals more; deepens insight');
insert into public.dimensions values (4, 'Critical Thinking & Adaptability', 'Ignores new information or challenge', 'Acknowledges it but keeps the original plan', 'Adjusts the approach to new information', 'Uses the change to deepen learning');
insert into public.dimensions values (5, 'Application / Skill Transfer', 'No link to the workplace', 'Generic link (“use this on the floor”)', 'Learner leaves with a specific action for a real situation', 'Action is measurable, owned and has a follow-up');
insert into public.dimensions values (6, 'Feedback & Judgement', 'Vague or misses key behaviours', 'Spots obvious points; feedback general', 'Spots critical and most clear points; feedback names behaviour, impact and alternative', 'Spots subtle points and prioritises what matters most');
