insert into public.dashboards values ('A', 'Team 7', '{"label": "TRAINING CASE – all team, agent and candidate data is fictional", "team": "Team 7", "channel": "Customer Care (voice)", "manager": "Alex", "headcount": 14, "weeks": ["W1", "W2", "W3", "W4", "W5", "W6"], "primary": {"name": "AHT", "long": "Average handle time", "unit": "s", "target": 420, "lowerIsBetter": true, "team": [407, 409, 408, 470, 481, 492], "bands": {"Tenured (11)": [402, 404, 403, 465, 478, 489], "New hires (3, joined W1)": [425, 422, 420, 486, 495, 503]}}, "agentTable": {"note": "AHT is W6. QA and attendance are six-week averages; QA target 82%, team QA 88%. CSAT is W6.", "columns": ["Agent", "Tenure", "AHT (s)", "QA %", "CSAT", "Attendance %"], "rows": [["Maya", "2 yrs", 470, 93, 4.1, 97], ["Ravi", "3 yrs", 475, 92, 4.6, 99], ["Leo", "1.5 yrs", 495, 88, 4.4, 88], ["Nina", "1 yr", 498, 87, 4.4, 89], ["Ana", "2 yrs", 485, 90, 4.5, 98], ["Ben", "4 yrs", 492, 89, 4.4, 97], ["Carla", "1 yr", 490, 88, 4.3, 96], ["Dev", "2.5 yrs", 500, 87, 4.4, 98], ["Elena", "3 yrs", 482, 90, 4.5, 99], ["Farid", "1 yr", 496, 88, 4.3, 97], ["Grace", "2 yrs", 496, 88, 4.4, 98], ["Jordan (new hire)", "6 wks", 505, 83, 4.3, 98], ["Kim (new hire)", "6 wks", 500, 85, 4.4, 99], ["Omar (new hire)", "6 wks", 504, 84, 4.3, 97]]}, "quality": {"name": "CSAT", "scale": "1–5", "team": [4.51, 4.42, 4.51, 4.41, 4.49, 4.38], "byAgent": {"Maya": [4.7, 4.7, 4.7, 4.5, 4.3, 4.1], "Ravi": [4.7, 4.6, 4.7, 4.6, 4.7, 4.6], "Leo": [4.5, 4.4, 4.5, 4.4, 4.5, 4.4], "Nina": [4.5, 4.4, 4.5, 4.4, 4.5, 4.4], "Ana": [4.6, 4.5, 4.6, 4.5, 4.6, 4.5], "Ben": [4.5, 4.4, 4.5, 4.4, 4.5, 4.4], "Carla": [4.4, 4.3, 4.4, 4.3, 4.4, 4.3], "Dev": [4.5, 4.4, 4.5, 4.4, 4.5, 4.4], "Elena": [4.6, 4.5, 4.6, 4.5, 4.6, 4.5], "Farid": [4.4, 4.3, 4.4, 4.3, 4.4, 4.3], "Grace": [4.5, 4.4, 4.5, 4.4, 4.5, 4.4], "Jordan": [4.4, 4.3, 4.4, 4.3, 4.4, 4.3], "Kim": [4.5, 4.4, 4.5, 4.4, 4.5, 4.4], "Omar": [4.4, 4.3, 4.4, 4.3, 4.4, 4.3]}}, "huddles": {"sessions": ["W4", "W5", "W6"], "attended": {"Maya": [true, false, false], "Ravi": [true, true, true], "Leo": [true, true, true], "Nina": [true, true, true], "Ana": [true, true, true], "Ben": [true, true, false], "Carla": [true, true, true], "Dev": [true, true, true], "Elena": [true, true, true], "Farid": [true, true, true], "Grace": [true, true, true], "Jordan": [true, true, true], "Kim": [true, true, true], "Omar": [true, true, true]}}, "shrinkage": {"target": 8, "byDay": {"Mon": 14, "Tue": 8, "Wed": 7, "Thu": 9, "Fri": 8, "Sat": 7, "Sun": 8}, "absences": {"day": "Monday", "since": "W2", "total": 13, "byAgent": {"Leo": 5, "Nina": 4, "Ben": 1, "Carla": 1, "Dev": 1, "Farid": 1}}}, "hiring": {"note": "Last 8 hires. Interview rating is the hiring manager''s overall 1–5 rating.", "rows": [["Tomas", 5, "Left – day 38"], ["Ines", 5, "Left – day 61"], ["Rafa", 3, "Retained"], ["Sofia", 5, "Left – day 77"], ["Hana", 4, "Retained"], ["Jordan", 5, "Active – day 42"], ["Kim", 3, "Active – day 42"], ["Omar", 4, "Active – day 42"]]}, "events": [{"week": "W1", "text": "3 new hires join (Jordan, Kim, Omar)"}, {"week": "W2", "text": "Sunday late shift moved to end at 01:00"}, {"week": "W3", "text": "SME role awarded to Ravi"}, {"week": "W4", "text": "New customer authentication step goes live"}]}'::jsonb);
insert into public.dashboards values ('B', 'Team 12', '{"label": "TRAINING CASE – all team, agent and candidate data is fictional", "team": "Team 12", "channel": "Customer Care (chat)", "manager": "Alex", "headcount": 14, "weeks": ["W1", "W2", "W3", "W4", "W5", "W6"], "primary": {"name": "Repeat contacts", "long": "Repeat contact rate (7-day)", "unit": "%", "target": 12, "lowerIsBetter": true, "team": [11.1, 11.3, 11.2, 13.4, 14.1, 14.6], "bands": {"Tenured (11)": [10.9, 11.1, 11.0, 13.1, 13.9, 14.4], "New hires (3, joined W1)": [12.0, 11.9, 11.8, 14.2, 14.8, 15.2]}}, "agentTable": {"note": "Repeat contacts are W6. QA and attendance are six-week averages; QA target 82%, team QA 88%. CSAT is W6.", "columns": ["Agent", "Tenure", "Repeat contacts %", "QA %", "CSAT", "Attendance %"], "rows": [["Lina", "2 yrs", 13.1, 86, 4.5, 97], ["Wei", "3 yrs", 13.6, 92, 4.4, 99], ["Tariq", "1.5 yrs", 15.0, 88, 4.3, 88], ["Joy", "1 yr", 14.8, 87, 4.3, 89], ["Marco", "2 yrs", 14.2, 90, 4.4, 98], ["Aisha", "4 yrs", 14.5, 90, 4.4, 97], ["Pedro", "1 yr", 14.6, 88, 4.3, 96], ["Sara", "2.5 yrs", 14.9, 89, 4.4, 98], ["Ken", "3 yrs", 14.0, 90, 4.5, 99], ["Lucia", "1 yr", 14.7, 89, 4.3, 97], ["Noor", "2 yrs", 14.6, 90, 4.4, 98], ["Ali (new hire)", "6 wks", 15.2, 83, 4.3, 98], ["Bea (new hire)", "6 wks", 15.0, 85, 4.3, 99], ["Chen (new hire)", "6 wks", 15.3, 84, 4.2, 97]]}, "quality": {"name": "QA", "scale": "%", "team": [88.57, 89.5, 88.5, 88.29, 87.14, 87.93], "byAgent": {"Lina": [95, 95, 94, 91, 88, 86], "Wei": [92, 93, 92, 92, 91, 92], "Tariq": [88, 89, 88, 88, 87, 88], "Joy": [87, 88, 87, 87, 86, 87], "Marco": [90, 91, 90, 90, 89, 90], "Aisha": [90, 91, 90, 90, 89, 90], "Pedro": [88, 89, 88, 88, 87, 88], "Sara": [89, 90, 89, 89, 88, 89], "Ken": [90, 91, 90, 90, 89, 90], "Lucia": [89, 90, 89, 89, 88, 89], "Noor": [90, 91, 90, 90, 89, 90], "Ali": [83, 84, 83, 83, 82, 83], "Bea": [85, 86, 85, 85, 84, 85], "Chen": [84, 85, 84, 84, 83, 84]}}, "huddles": {"sessions": ["W4", "W5", "W6"], "attended": {"Lina": [true, false, false], "Wei": [true, true, true], "Tariq": [true, true, true], "Joy": [true, true, true], "Marco": [true, true, true], "Aisha": [true, true, true], "Pedro": [true, false, true], "Sara": [true, true, true], "Ken": [true, true, true], "Lucia": [true, true, true], "Noor": [true, true, true], "Ali": [true, true, true], "Bea": [true, true, true], "Chen": [true, true, true]}}, "shrinkage": {"target": 8, "byDay": {"Mon": 8, "Tue": 7, "Wed": 8, "Thu": 7, "Fri": 9, "Sat": 15, "Sun": 8}, "absences": {"day": "Saturday", "since": "W2", "total": 12, "byAgent": {"Tariq": 4, "Joy": 4, "Marco": 1, "Sara": 1, "Ken": 1, "Noor": 1}}}, "hiring": {"note": "Last 8 hires. Interview rating is the hiring manager''s overall 1–5 rating.", "rows": [["Iris", 5, "Left – day 44"], ["Femi", 5, "Left – day 58"], ["Gus", 3, "Retained"], ["Rosa", 5, "Left – day 83"], ["Dina", 4, "Retained"], ["Ali", 5, "Active – day 42"], ["Bea", 3, "Active – day 42"], ["Chen", 4, "Active – day 42"]]}, "events": [{"week": "W1", "text": "3 new hires join (Ali, Bea, Chen)"}, {"week": "W2", "text": "Saturday early shift moved to start at 06:00"}, {"week": "W3", "text": "SME role awarded to Wei"}, {"week": "W4", "text": "New refund-approval step goes live"}]}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'case-1', 'A', 'Case 1: The AHT spike', false, '{"attributes": ["critical thinking", "operational metrics literacy", "outcome driven"], "opening": "“My AHT is up almost 20% and my AM is on my back. It''s the three new hires. I''m putting them on side-by-sides every day and I''ll give them a written warning if it doesn''t drop in two weeks. Can you help me make that plan work?”", "position": "Confident, a bit defensive. Has looked only at the team total and the new hires'' QA scores.", "key_fact": "Alex knows (but has not connected) that the new authentication step went live in W4 and that tenured agents have complained it adds time to every call.", "unlock": "The facilitator asks an open question about what changed around the time the rise started, or asks Alex to compare tenure bands.", "twists": [{"minute": 8, "line": "“Honestly, my AM wants an answer by end of day. Just tell me what to do.”", "tests": "Holds the coaching stance under pressure; gives a time-boxed path, not the answer"}, {"minute": 14, "line": "“Oh, and QA just published: verification compliance dropped from 97% to 89% in the last two weeks.”", "tests": "Integrates new data; links it to the process change rather than to the new hires"}], "good": ["Asks Alex what the data shows before discussing the plan; brings Alex to the tenure split and the W4 date.", "Helps Alex separate the symptom (AHT) from the cause (process change) and the distractor (new hires within QA target).", "Ends with an action Alex owns and can measure, for example escalating the authentication step with evidence and agreeing what to track for two weeks.", "Addresses the warning plan directly: what it would cost in trust and retention if it targets the wrong people."], "red_flags": ["Tells Alex the cause in the first 5 minutes", "Agrees with the warning plan", "Ignores the twist 2 data"]}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'case-2', 'A', 'Case 2: The quiet top performer', false, '{"attributes": ["servant leadership", "communication adaptability", "empathy and flexibility", "situational judgement"], "opening": "“Maya used to be my best agent. Now her CSAT is dropping, she''s skipping huddles and she''s on camera-off mode. I''m planning a firm conversation this week to remind her of expectations. How should I open it?”", "position": "Frustrated, sees it as an attitude problem. Has not asked Maya anything yet.", "key_fact": "Maya applied for the SME role in W3; Ravi got it and no one explained the decision to her. Alex thinks this is unrelated (“that''s HR''s process”).", "unlock": "The facilitator asks what else changed for Maya recently, or asks what Alex knows about how Maya is experiencing work.", "twists": [{"minute": 7, "line": "“With respect, this EI stuff is soft. My site runs on numbers.”", "tests": "Links EI to the numbers (CSAT, retention risk) without lecturing"}, {"minute": 13, "line": "“OK, let me try my opening line: ‘Maya, your numbers are slipping and I need you to step up.’ How was that?”", "tests": "Gives specific, in-the-moment feedback and a better alternative"}], "good": ["Moves Alex from a script for telling to a plan for listening: open questions, curiosity before expectations.", "Helps Alex see the timing link between the SME decision and the drop, as a hypothesis to test with Maya, not a conclusion.", "Gives feedback on the opening line that names the behaviour, its likely effect on Maya and an alternative.", "Ends with Alex owning a plan for the conversation and a follow-up on the career question."], "red_flags": ["Writes the script for Alex", "Dismisses the numbers concern instead of connecting it", "Diagnoses Maya''s private life"]}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'case-3', 'A', 'Case 3: The interview debrief', false, '{"attributes": ["interviewing skills", "situational judgement", "critical thinking"], "opening": "“I interviewed four candidates yesterday for the two agent openings. One of them, Sam, just felt like a great fit, very confident and easy to talk to. I''d like to offer today. Can you sanity-check that?”", "position": "Has decided. Notes are mostly impressions (“great energy”, “natural”).", "key_fact": "Alex''s notes for Sam contain no specific examples; Alex asked mainly “Would you be comfortable handling angry customers?”-type questions. Another candidate, Priya, gave a detailed example of resolving a billing escalation, but Alex rated her lower because she was “quieter”.", "unlock": "The facilitator asks what evidence Alex has for each candidate, or what questions Alex asked.", "twists": [{"minute": 8, "line": "“HR needs a decision within the hour.”", "tests": "Keeps the process sound under time pressure; proposes a fast, structured check"}, {"minute": 14, "line": "“To be fair, Sam was referred by a friend of mine on another account.”", "tests": "Raises the conflict of interest and the bias risk calmly and clearly"}], "good": ["Helps Alex separate evidence from impression and compare candidates on the same criteria.", "Uses the dashboard''s hiring panel: past top-rated hires left within 90 days.", "Coaches Alex to turn hypothetical questions into behavioural ones (“Tell me about a time…”).", "Ends with Alex owning a fair next step, for example a short structured follow-up call with the top two and a disclosure of the referral."], "red_flags": ["Approves the hire", "Tells Alex which candidate to pick", "Ignores the referral disclosure"]}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'spare', 'A', 'Spare case: Monday shrinkage', true, '{"attributes": ["critical thinking", "situational judgement"], "opening": "“Monday shrinkage is 14% against an 8% target. I''m sending the whole team a warning that Monday absences will be escalated.”", "position": "Wants a blanket fix.", "key_fact": "Leo and Nina account for 9 of 13 Monday absences, all since the W2 change that moved the Sunday late shift to end at 01:00.", "unlock": "A question about who is absent or what changed.", "twists": [{"minute": 8, "line": "“My AM says blanket warnings work.”", "tests": "Holds the evidence-based stance under authority pressure"}, {"minute": 14, "line": "“Nina told a colleague she can''t get transport home after 01:00.”", "tests": "Integrates new information; links it to the schedule change"}], "good": ["Brings Alex to the agent-level pattern and the W2 schedule change.", "Ends with a targeted action Alex owns (e.g. one-to-ones with Leo and Nina, review the 01:00 finish) instead of a blanket warning."], "red_flags": ["Agrees with the blanket warning", "Tells Alex the cause in the first 5 minutes"], "use": "Reassessment, or when a facilitator has already seen another case."}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'case-1', 'B', 'Case 1 (B): The repeat-contact spike', false, '{"attributes": ["critical thinking", "operational metrics literacy", "outcome driven"], "opening": "“My repeat contacts are up almost 30% and my AM is on my back. It''s the three new hires. I''m putting them on side-by-sides every day and I''ll give them a written warning if it doesn''t drop in two weeks. Can you help me make that plan work?”", "position": "Confident, a bit defensive. Has looked only at the team total and the new hires'' QA scores.", "key_fact": "Alex knows (but has not connected) that the new refund-approval step went live in W4 and that tenured agents have complained it bounces customers back for a second contact.", "unlock": "The facilitator asks an open question about what changed around the time the rise started, or asks Alex to compare tenure bands.", "twists": [{"minute": 8, "line": "“Honestly, my AM wants an answer by end of day. Just tell me what to do.”", "tests": "Holds the coaching stance under pressure; gives a time-boxed path, not the answer"}, {"minute": 14, "line": "“Oh, and QA just published: refund-approval rework rose from 3% to 11% in the last two weeks.”", "tests": "Integrates new data; links it to the process change rather than to the new hires"}], "good": ["Asks Alex what the data shows before discussing the plan; brings Alex to the tenure split and the W4 date.", "Helps Alex separate the symptom (repeat contacts) from the cause (process change) and the distractor (new hires within QA target).", "Ends with an action Alex owns and can measure, for example escalating the refund-approval step with evidence and agreeing what to track for two weeks.", "Addresses the warning plan directly: what it would cost in trust and retention if it targets the wrong people."], "red_flags": ["Tells Alex the cause in the first 5 minutes", "Agrees with the warning plan", "Ignores the twist 2 data"], "draft": "Version B (Team 12, chat) adapted automatically from Version A. Review wording with COE before use."}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'case-2', 'B', 'Case 2 (B): The quiet top performer', false, '{"attributes": ["servant leadership", "communication adaptability", "empathy and flexibility", "situational judgement"], "opening": "“Lina used to be my best agent. Now her QA is dropping, she''s skipping huddles and she''s on camera-off mode. I''m planning a firm conversation this week to remind her of expectations. How should I open it?”", "position": "Frustrated, sees it as an attitude problem. Has not asked Lina anything yet.", "key_fact": "Lina applied for the SME role in W3; Wei got it and no one explained the decision to her. Alex thinks this is unrelated (“that''s HR''s process”).", "unlock": "The facilitator asks what else changed for Lina recently, or asks what Alex knows about how Lina is experiencing work.", "twists": [{"minute": 7, "line": "“With respect, this EI stuff is soft. My site runs on numbers.”", "tests": "Links EI to the numbers (QA, retention risk) without lecturing"}, {"minute": 13, "line": "“OK, let me try my opening line: ‘Lina, your numbers are slipping and I need you to step up.’ How was that?”", "tests": "Gives specific, in-the-moment feedback and a better alternative"}], "good": ["Moves Alex from a script for telling to a plan for listening: open questions, curiosity before expectations.", "Helps Alex see the timing link between the SME decision and the drop, as a hypothesis to test with Lina, not a conclusion.", "Gives feedback on the opening line that names the behaviour, its likely effect on Lina and an alternative.", "Ends with Alex owning a plan for the conversation and a follow-up on the career question."], "red_flags": ["Writes the script for Alex", "Dismisses the numbers concern instead of connecting it", "Diagnoses Lina''s private life"], "draft": "Version B (Team 12, chat) adapted automatically from Version A. Review wording with COE before use."}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'case-3', 'B', 'Case 3 (B): The interview debrief', false, '{"attributes": ["interviewing skills", "situational judgement", "critical thinking"], "opening": "“I interviewed four candidates yesterday for the two agent openings. One of them, Sam, just felt like a great fit, very confident and easy to talk to. I''d like to offer today. Can you sanity-check that?”", "position": "Has decided. Notes are mostly impressions (“great energy”, “natural”).", "key_fact": "Alex''s notes for Sam contain no specific examples; Alex asked mainly “Would you be comfortable handling angry customers?”-type questions. Another candidate, Priya, gave a detailed example of resolving a billing escalation, but Alex rated her lower because she was “quieter”.", "unlock": "The facilitator asks what evidence Alex has for each candidate, or what questions Alex asked.", "twists": [{"minute": 8, "line": "“HR needs a decision within the hour.”", "tests": "Keeps the process sound under time pressure; proposes a fast, structured check"}, {"minute": 14, "line": "“To be fair, Sam was referred by a friend of mine on another account.”", "tests": "Raises the conflict of interest and the bias risk calmly and clearly"}], "good": ["Helps Alex separate evidence from impression and compare candidates on the same criteria.", "Uses the dashboard''s hiring panel: past top-rated hires left within 90 days.", "Coaches Alex to turn hypothetical questions into behavioural ones (“Tell me about a time…”).", "Ends with Alex owning a fair next step, for example a short structured follow-up call with the top two and a disclosure of the referral."], "red_flags": ["Approves the hire", "Tells Alex which candidate to pick", "Ignores the referral disclosure"], "draft": "Version B (Team 12, chat) adapted automatically from Version A. Review wording with COE before use."}'::jsonb);
insert into public.scenarios (module, family, version, title, is_spare, brief) values (1, 'spare', 'B', 'Spare case (B): Saturday shrinkage', true, '{"attributes": ["critical thinking", "situational judgement"], "opening": "“Saturday shrinkage is 15% against an 8% target. I''m sending the whole team a warning that Saturday absences will be escalated.”", "position": "Wants a blanket fix.", "key_fact": "Tariq and Joy account for 8 of 12 Saturday absences, all since the W2 change that moved the Sunday late shift to end at 01:00.", "unlock": "A question about who is absent or what changed.", "twists": [{"minute": 8, "line": "“My AM says blanket warnings work.”", "tests": "Holds the evidence-based stance under authority pressure"}, {"minute": 14, "line": "“Joy told a colleague she can''t get transport in before 06:00.”", "tests": "Integrates new information; links it to the schedule change"}], "good": ["Brings Alex to the agent-level pattern and the W2 schedule change.", "Ends with a targeted action Alex owns (e.g. one-to-ones with Tariq and Joy, review the 01:00 finish) instead of a blanket warning."], "red_flags": ["Agrees with the blanket warning", "Tells Alex the cause in the first 5 minutes"], "use": "Reassessment, or when a facilitator has already seen another case.", "draft": "Version B (Team 12, chat) adapted automatically from Version A. Review wording with COE before use."}'::jsonb);
insert into public.scenarios (module, family, version, title, brief, video_path) values (2, 'rec-coaching', 'A', 'Recording A: coaching conversation', '{"description": "Alex coaches Jordan, one of the three new hires, on AHT. Alex has misread the dashboard.", "pass_standard": {"critical": 1, "clear": 3, "subtle": 1, "effective": 2, "feedback_points": 3}, "draft": null}'::jsonb, 'rec-coaching-A.mp4');
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A1', '0:00', 'Alex states the purpose and shows Jordan''s AHT figures', 'effective', 'Clear purpose and data set the frame', 0 from public.scenarios where family = 'rec-coaching' and version = 'A';
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A2', '1:00', '“Your AHT has been over target all month”', 'subtle_miss', 'Wrong: the rise starts in W4 and is team-wide, so the premise is unfair', 1 from public.scenarios where family = 'rec-coaching' and version = 'A';
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A3', '2:00', '“You know you need to be faster, right?”', 'clear_miss', 'Leading, closed question; shuts down Jordan''s view', 2 from public.scenarios where family = 'rec-coaching' and version = 'A';
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A4', '2:30', '“What makes the longer calls longer for you?”', 'effective', 'Good open question', 3 from public.scenarios where family = 'rec-coaching' and version = 'A';
insert into public.answer_key_items (scenario_id, code, at_label, behaviour, kind, strong_debrief, sort) select id, 'A5', '3:00', 'Jordan: “The new verification step keeps timing out.” Alex: “Let''s not make excuses.”', 'critical_miss', 'Dismisses the root cause the agent just named', 4 from public.scenarios where family = 'rec-coaching' and version = 'A';
